        <div style={{fontWeight: 800, opacity: 0.8}}>레이어마다 다른 속도 · translateX</div>
        {LEGEND.map(([k, v]) => <div key={k}><b>{k}</b> <span style={{color: GOLD, fontWeight: 800}}>{v}</span></div>)}
      </div>
    </AbsoluteFill>
  );
};

