const EASINGS = [
  {name: 'Easing.linear', fn: Easing.linear},
  {name: 'Easing.inOut(Easing.cubic)', fn: Easing.inOut(Easing.cubic)},
  {name: 'Easing.out(Easing.back(1.7))', fn: Easing.out(Easing.back(1.7))},
